# Batch 6 generator — Scenarios 87-96 (Appeals & Post-Permanency). House schema, v1 formats.
import json
from datetime import date, timedelta

ROUTES = {}   # scen_num -> {node_id: win_choice_index}
BUILT = {}

def kf(start, off):
    d = start + timedelta(days=off)
    return f"Day {off} \u2014 {d.strftime('%A, %B')} {d.day}, {d.year}"

def C(text, nxt, win=False, **kw):
    c = {"text": text, "next": nxt}
    for k in ("cash", "setFlags", "addHidden", "note", "requiresFlags", "requiresNoFlags"):
        if k in kw:
            c[k] = kw[k]
    if win:
        c["_win"] = True
    return c

def N(nid, off, title, body, choices, kicker=None):
    return {"id": nid, "_off": off, "title": title, "body": body, "choices": choices, "_kicker": kicker}

def E(nid, off, title, body, debrief, kicker=None):
    return {"id": nid, "_off": off, "title": title, "body": body, "ending": True, "debrief": debrief, "_kicker": kicker}

def build(num, meta, start, nodes):
    route = {}
    out = []
    for n in nodes:
        m = {"id": n["id"], "kicker": n["_kicker"] or kf(start, n["_off"]), "dayOffset": n["_off"],
             "title": n["title"], "body": n["body"]}
        if n.get("ending"):
            m["ending"] = True
            m["debrief"] = n["debrief"]
        else:
            chs = []
            for i, c in enumerate(n["choices"]):
                c = dict(c)
                if c.pop("_win", False):
                    route[n["id"]] = i
                chs.append(c)
            m["choices"] = chs
        out.append(m)
    meta = dict(meta)
    meta["startDateISO"] = start.isoformat()
    doc = {"meta": meta, "nodes": out}
    with open(f"scenario-{num}.json", "w") as f:
        json.dump(doc, f, indent=1, ensure_ascii=False)
    ROUTES[num] = route
    BUILT[num] = doc
    print(f"scenario-{num}: {len(out)} nodes")

